function topoSort(graph) {
  const deps = {};
  const tasks = new Set();

  for (const name of Object.keys(graph)) {
    tasks.add(name);
    const list = graph[name];
    const unique = new Set();
    for (const dep of list) {
      unique.add(dep);
      tasks.add(dep);
    }
    deps[name] = [...unique];
  }

  for (const name of tasks) {
    if (!deps[name]) deps[name] = [];
  }

  const placed = new Set();
  const result = [];

  while (result.length < tasks.size) {
    let next = null;
    for (const name of tasks) {
      if (placed.has(name)) continue;
      const ready = deps[name].every((d) => placed.has(d));
      if (ready && (next === null || name < next)) {
        next = name;
      }
    }
    if (next === null) {
      throw new Error('cycle detected');
    }
    placed.add(next);
    result.push(next);
  }

  return result;
}

