def business_days(start, end, holidays=()):
    def parse(s):
        try:
            return date.fromisoformat(s)
        except ValueError:
            raise ValueError(f"invalid date: {s!r}")

    start_d = parse(start)
    end_d = parse(end)
    if end_d < start_d:
        raise ValueError("end must not be earlier than start")

    holiday_set = set()
    for h in holidays:
