  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  const parts = spec.split(',');
  const set = new Set();

  for (const raw of parts) {
    const part = raw.trim();
    if (part === '') {
      throw new SyntaxError('empty part');
    }

    const dashIndex = part.indexOf('-');
    if (dashIndex !== -1) {
      const lo = part.slice(0, dashIndex);
      const hi = part.slice(dashIndex + 1);
      if (!/^\d+$/.test(lo) || !/^\d+$/.test(hi)) {
        throw new SyntaxError('invalid range');
      }
      const start = parseInt(lo, 10);
      const end = parseInt(hi, 10);
      if (start > end) {
        throw new RangeError('range start greater than end');
      }
      for (let i = start; i <= end; i++) {
        set.add(i);
      }
    } else {
      if (!/^\d+$/.test(part)) {
        throw new SyntaxError('invalid number');
      }
      set.add(parseInt(part, 10));
    }
  }

  return Array.from(set).sort((a, b) => a - b);
}

