import re

_NUM = r'(?:0|[1-9]\d*)'
_IDENT = r'[0-9A-Za-z-]+'
_PRERELEASE = r'(?:' + _IDENT + r'(?:\.' + _IDENT + r')*)'
_BUILD = r'(?:' + _IDENT + r'(?:\.' + _IDENT + r')*)'

_VERSION_RE = re.compile(
    r'^(' + _NUM + r')\.(' + _NUM + r')\.(' + _NUM + r')'
    r'(?:-(' + _PRERELEASE + r'))?'
    r'(?:\+(' + _BUILD + r'))?$'
)


def compare_versions(a, b):
    def parse(s):
        m = _VERSION_RE.match(s)
        if not m:
            raise ValueError('invalid version: %r' % s)
        major, minor, patch, prerelease, build = m.groups()
        return (int(major), int(minor), int(patch), prerelease)

    va, vb = parse(a), parse(b)
    if va[:3] != vb[:3]:
        return -1 if va[:3] < vb[:3] else 1

    pa, pb = va[3], vb[3]
    if pa is None and pb is None:
        return 0
    if pa is None:
        return 1
    if pb is None:
        return -1

    ia, ib = pa.split('.'), pb.split('.')
    for x, y in zip(ia, ib):
        if x == y:
            continue
        xd, yd = x.isdigit(), y.isdigit()
        if xd and yd:
            return -1 if int(x) < int(y) else 1
        if xd:
            return -1
        if yd:
            return 1
        return -1 if x < y else 1
    return -1 if len(ia) < len(ib) else (1 if len(ia) > len(ib) else 0)
