    return "".join(out)

def rle_decode(s):
    if not isinstance(s, str):
        raise TypeError("input must be a string")
    if s == "":
        return ""
    pattern = re.compile(r"(\d+)(\D)")
    pos = 0
    out = []
    while pos < len(s):
        m = pattern.match(s, pos)
        if not m:
            raise ValueError("invalid RLE string")
        count = int(m.group(1))
        if count == 0:
            raise ValueError("count must be at least 1")
        out.append(m.group(2) * count)
        pos = m.end()
    return "".join(out)
