function addDays(dateStr, days) {
  if (typeof dateStr !== 'string') {
    throw new TypeError('dateStr must be a string');
  }
  if (!Number.isInteger(days)) {
    throw new TypeError('days must be an integer');
  }

  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(dateStr);
  if (!m) {
    throw new RangeError('dateStr must match YYYY-MM-DD');
  }

  const year = parseInt(m[1], 10);
  const month = parseInt(m[2], 10);
  const day = parseInt(m[3], 10);

  if (year < 1 || year > 9999) {
    throw new RangeError('year out of range');
  }

  const daysInMonth = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  const isLeap = (y) => (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
  if (month < 1 || month > 12) {
    throw new RangeError('month out of range');
  }
  const dim = daysInMonth[month - 1] + (month === 2 && isLeap(year) ? 1 : 0);
  if (day < 1 || day > dim) {
    throw new RangeError('day out of range');
  }

  const d = new Date(Date.UTC(year, month - 1, day));
  d.setUTCDate(d.getUTCDate() + days);

  const y = d.getUTCFullYear();
  if (y < 1 || y > 9999) {
    throw new RangeError('result year out of range');
  }

  const mo = String(d.getUTCMonth() + 1).padStart(2, '0');
  const dy = String(d.getUTCDate()).padStart(2, '0');
  return String(y).padStart(4, '0') + '-' + mo + '-' + dy;
}

module.exports = { addDays };
