    if not n[0].isalpha():
        raise ValueError("invalid username")
    if n[-1] in "_.":
        raise ValueError("invalid username")
    for i in range(len(n) - 1):
        if n[i] in "_.":
            if n[i + 1] in "_.":
                raise ValueError("invalid username")
    return n

